                "Merksatz: Sono di Berlino nennt den Ort. Sono tedesco nennt die Nationalität. Sono kann außerdem „ich bin“ oder „sie sind“ bedeuten – der Zusammenhang macht klar, wer gemeint ist.",
            ],
            dialogue: [
                DialogueLine(id: "3-d1", speaker: "IO", italian: "Io sono di Berlino.", german: "Ich komme aus Berlin."),
                DialogueLine(id: "3-d2", speaker: "TU", italian: "Tu sei di Roma.", german: "Du kommst aus Rom."),
                DialogueLine(id: "3-d3", speaker: "LUI", italian: "Lui è di Milano.", german: "Er kommt aus Mailand."),
                DialogueLine(id: "3-d4", speaker: "NOI", italian: "Noi siamo di Berlino.", german: "Wir kommen aus Berlin."),
                DialogueLine(id: "3-d5", speaker: "VOI", italian: "Voi siete di Roma.", german: "Ihr kommt aus Rom."),
                DialogueLine(id: "3-d6", speaker: "LORO", italian: "Loro sono di Milano.", german: "Sie kommen aus Mailand."),
