            notes: [
                LessonNote(id: "4-n1", title: "Abitare – wohnen · alle Formen", body: "Die Endung zeigt, wer wohnt. Die drei Formen der Einzahl und die drei Formen der Mehrzahl folgen einem regelmäßigen Muster: io abito io abito ich wohne tu abiti tu abiti du wohnst lui / lei / Lei abita lui / läi / läi abita er / sie wohnt · Sie wohnen noi abitiamo noi abitjamo wir wohnen voi abitate voi abitate ihr wohnt · Sie wohnen (Mehrzahl) loro abitano loro abitano sie wohnen IO Io abito a Berlino. Ich wohne in Berlin. TU Tu abiti a Roma. Du wohnst in Rom. LEI Lei abita a Milano. Sie wohnen in Mailand. NOI Noi abitiamo a Berlino. Wir wohnen in Berlin. VOI Voi abitate a Roma. Ihr wohnt in Rom. LORO Tom e Mark abitano in Germania. Tom und Mark wohnen in Deutschland. Tom e Mark sind mehrere Personen und funktionieren deshalb wie loro : Tom e Mark abitano . Im Gespräch fällt ein Pronomen meistens weg, wenn die Verbform schon zeigt, wer gemeint ist."),
                LessonNote(id: "4-n2", title: "Aussage oder Frage? Die Wortfolge bleibt gleich", body: "Im Italienischen wird eine Aussage meist nur durch die steigende Stimme zur Frage. Es gibt kein zusätzliches Hilfsverb wie im Englischen und die Wörter werden nicht umgestellt. Person Aussage Frage io Io abito in Italia. Abito in Italia? tu Tu abiti in Italia. Abiti in Italia? lui / lei Lui / lei abita in Italia. Abita in Italia? Lei Lei abita in Italia. Abita in Italia? noi Noi abitiamo in Italia. Abitiamo in Italia? voi Voi abitate in Italia. Abitate in Italia? loro Loro abitano in Italia. Abitano in Italia? Die Pronomen dienen hier zur Orientierung. Natürlicher sind meistens die kurzen Formen: Abiti in Italia? , Abitate in Italia? oder Abitano in Italia? Der Zusammenhang zeigt, wer gemeint ist."),
                LessonNote(id: "4-n3", title: "Verstehen: a bei Städten, in bei Ländern", body: "Vor einer Stadt steht normalerweise a : Abito a Berlino. Vor einem Land steht normalerweise in : Abito in Germania. Beides lässt sich verbinden: Abito a Berlino, in Germania."),
                LessonNote(id: "4-n4", title: "Verstehen: Verneinen mit non", body: "Non bedeutet meist „nicht“ und steht direkt vor dem Verb. Du musst das Verb dafür nicht verändern. Non abito a Milano. non abito a milano Ich wohne nicht in Mailand. Non sono italiano. non sono italjano Ich bin kein Italiener. Non voglio un caffè. non wolljo un kaffe Ich möchte keinen Kaffee. Non sto bene. non sto bene Mir geht es nicht gut. No heißt allein „Nein“. Non verneint dagegen einen Satz: No, non abito a Milano. – Nein, ich wohne nicht in Mailand. Bei einer Ja-Nein-Frage bleibt die Wortfolge einfach: Abiti a Milano? – Wohnst du in Mailand? Die vollständige Antwort aus der Folge lautet: No, non abito a Milano. Abito a Trieste."),
            ],
            memories: [
                "Merksatz: a Berlino für eine Stadt, in Germania für ein Land.",
            ],
            dialogue: [
                DialogueLine(id: "4-d1", speaker: "IO", italian: "Io abito a Berlino.", german: "Ich wohne in Berlin."),
                DialogueLine(id: "4-d2", speaker: "TU", italian: "Tu abiti a Roma.", german: "Du wohnst in Rom."),
                DialogueLine(id: "4-d3", speaker: "LEI", italian: "Lei abita a Milano.", german: "Sie wohnen in Mailand."),
                DialogueLine(id: "4-d4", speaker: "NOI", italian: "Noi abitiamo a Berlino.", german: "Wir wohnen in Berlin."),
                DialogueLine(id: "4-d5", speaker: "VOI", italian: "Voi abitate a Roma.", german: "Ihr wohnt in Rom."),
                DialogueLine(id: "4-d6", speaker: "LORO", italian: "Tom e Mark abitano in Germania.", german: "Tom und Mark wohnen in Deutschland."),
                DialogueLine(id: "4-d7", speaker: "A", italian: "Dove abiti?", german: "Wo wohnst du?"),
                DialogueLine(id: "4-d8", speaker: "B", italian: "Abito a Berlino, in Germania. E tu?", german: "Ich wohne in Berlin, in Deutschland. Und du?"),
                DialogueLine(id: "4-d9", speaker: "A", italian: "Abito a Roma, in Italia.", german: "Ich wohne in Rom, in Italien."),
            ]
        ),
        ItalianLesson(
            id: 5,
            shortTitle: "Familie",
            title: "Meine Familie – Personen vorstellen und Geschwister",
            goal: "Familienmitglieder vorstellen, nach Geschwistern fragen und mit ho , hai und non ho antworten.",
            icon: "figure.2.and.child.holdinghands",
            phrases: [
                LessonPhrase(id: "5-p1", italian: "Questo è mio padre.", pronunciation: "kwesto e mio padre", german: "Das ist mein Vater."),
                LessonPhrase(id: "5-p2", italian: "Questa è mia madre.", pronunciation: "kwesta e mia madre", german: "Das ist meine Mutter."),
                LessonPhrase(id: "5-p3", italian: "Questo è mio figlio.", pronunciation: "kwesto e mio filjo", german: "Das ist mein Sohn."),
                LessonPhrase(id: "5-p4", italian: "Questa è mia moglie.", pronunciation: "kwesta e mia mollje", german: "Das ist meine Ehefrau."),
                LessonPhrase(id: "5-p5", italian: "Come si chiama tua madre?", pronunciation: "kome si kjama tua madre", german: "Wie heißt deine Mutter?"),
                LessonPhrase(id: "5-p6", italian: "Si chiama …", pronunciation: "si kjama", german: "Er / Sie heißt …"),
                LessonPhrase(id: "5-p7", italian: "Ho un fratello.", pronunciation: "o un fratello", german: "Ich habe einen Bruder."),
                LessonPhrase(id: "5-p8", italian: "Hai fratelli o sorelle?", pronunciation: "ai fratelli o sorelle", german: "Hast du Brüder oder Schwestern?"),
                LessonPhrase(id: "5-p9", italian: "Hai un fratello?", pronunciation: "ai un fratello", german: "Hast du einen Bruder?"),
                LessonPhrase(id: "5-p10", italian: "Hai una sorella?", pronunciation: "ai una sorella", german: "Hast du eine Schwester?"),
                LessonPhrase(id: "5-p11", italian: "Ho una sorella.", pronunciation: "o una sorella", german: "Ich habe eine Schwester."),
                LessonPhrase(id: "5-p12", italian: "Ho due fratelli.", pronunciation: "o due fratelli", german: "Ich habe zwei Brüder."),
                LessonPhrase(id: "5-p13", italian: "No, non ho fratelli.", pronunciation: "no, non o fratelli", german: "Nein, ich habe keine Brüder."),
                LessonPhrase(id: "5-p14", italian: "No, non ho sorelle.", pronunciation: "no, non o sorelle", german: "Nein, ich habe keine Schwestern."),
                LessonPhrase(id: "5-p15", italian: "Non ho fratelli o sorelle.", pronunciation: "non o fratelli o sorelle", german: "Ich habe keine Brüder oder Schwestern."),
            ],
            notes: [
                LessonNote(id: "5-n1", title: "Verstehen: mio bei männlichen, mia bei weiblichen Wörtern", body: "Mio und mia bedeuten beide „mein/meine“. Welche Form du benutzt, richtet sich nach dem italienischen Wort , nicht nach der Person, die spricht. Männlich Weiblich Deutsch mio padre mia madre mein Vater / meine Mutter mio fratello mia sorella mein Bruder / meine Schwester mio figlio mia figlia mein Sohn / meine Tochter mio marito mia moglie mein Ehemann / meine Ehefrau Merke: Die Endung hilft dir oft: -o → mio , -a → mia . Das ist eine gute Lernhilfe, aber keine allgemeine Regel für jedes italienische Substantiv."),
                LessonNote(id: "5-n2", title: "Verstehen: questo oder questa?", body: "Questo verwendest du hier mit einem männlichen Wort: Questo è mio padre. Questa verwendest du hier mit einem weiblichen Wort: Questa è mia madre. Das Muster kennst du schon: Im Italienischen passen sich viele kleine Wörter an männlich/weiblich an – ähnlich wie bei buon/buona aus Lektion 1–02."),
                LessonNote(id: "5-n3", title: "Verstehen: mi chiamo und si chiama", body: "Mi chiamo Tobias. = Ich heiße Tobias. Si chiama Luca. = Er heißt Luca. / Sie heißt Luca. Das si kennst du schon aus der höflichen Frage Come si chiama? . Der Kontext zeigt dir, ob „Sie heißen“ oder „er/sie heißt“ gemeint ist."),
                LessonNote(id: "5-n4", title: "Verstehen: ho, hai und non ho", body: "Ho = ich habe · hai = du hast · non ho = ich habe nicht / ich habe keine. Das h bleibt stumm: ho klingt wie „o“, hai wie „ai“. un fratello ist männlich, una sorella weiblich. Im Plural wird daraus fratelli und sorelle ."),
            ],
            memories: [
                "Merksatz: mio padre / mia madre und questo / questa richten sich nach dem männlichen oder weiblichen Wort. Mit ho sagst du, wen du hast: Ho due fratelli.",
            ],
            dialogue: [
                DialogueLine(id: "5-d1", speaker: "A", italian: "Hai fratelli o sorelle?", german: "Hast du Brüder oder Schwestern?"),
                DialogueLine(id: "5-d2", speaker: "B", italian: "Sì, ho due fratelli.", german: "Ja, ich habe zwei Brüder."),
                DialogueLine(id: "5-d3", speaker: "A", italian: "Come si chiama tuo fratello?", german: "Wie heißt dein Bruder?"),
                DialogueLine(id: "5-d4", speaker: "B", italian: "Si chiama Luca.", german: "Er heißt Luca."),
            ]
        ),
    ]

    static var featuredVocabulary: [VocabularyItem] {
        vocabulary.filter { [.essential, .restaurant, .travel, .smallTalk].contains($0.category) }
    }

    static func makeQuiz(limit: Int = 10, category: VocabularyCategory? = nil) -> [QuizQuestion] {
        let source = category.map { selected in
            vocabulary.filter { $0.category == selected }
        } ?? vocabulary

        let usable = source.filter { !$0.italian.contains(" / ") && $0.german.count < 110 }
        let selected = Array(usable.shuffled().prefix(min(limit, usable.count)))

        return selected.map { item in
            let distractors = Set(vocabulary
                .filter { $0.id != item.id && $0.german != item.german && $0.german.count < 110 }
                .map(\.german))
                .shuffled()
                .prefix(3)

            return QuizQuestion(
                wordID: item.id,
                italian: item.italian,
                pronunciation: item.pronunciation,
                answers: ([item.german] + Array(distractors)).shuffled(),
                correctAnswer: item.german
            )
        }
    }

    static func makeQuiz(wordIDs: Set<Int>, limit: Int = 10) -> [QuizQuestion] {
        let items = vocabulary.filter { wordIDs.contains($0.id) }
        let selected = Array(items.shuffled().prefix(min(limit, items.count)))

        return selected.map { item in
            let distractors = Set(vocabulary
                .filter { $0.id != item.id && $0.german != item.german && $0.german.count < 110 }
                .map(\.german))
                .shuffled()
                .prefix(3)

            return QuizQuestion(
                wordID: item.id,
                italian: item.italian,
                pronunciation: item.pronunciation,
                answers: ([item.german] + Array(distractors)).shuffled(),
                correctAnswer: item.german
            )
        }
    }

    static func groups(from items: [VocabularyItem]) -> [VocabularyGroup] {
        var order: [String] = []
        var grouped: [String: [VocabularyItem]] = [:]

        for item in items {
            if grouped[item.section] == nil { order.append(item.section) }
            grouped[item.section, default: []].append(item)
        }

        return order.map { VocabularyGroup(title: $0, items: grouped[$0] ?? []) }
    }
}
